contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= address(this).balance == false ? false : true);
        amount = bound(amount, 1, 1e30);
