pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit, uint256 amount) public {
        deposit = bound(deposit, 1, type(uint128).max);
        amount = bound(amount, 0, deposit - 1);
        vm.assume(amount < deposit);
        // fund the test contract (it is the owner) and deposit into c via fallback
        vm.deal(address(this), deposit);
        (bool sent, ) = address(c).call{value: deposit}("");
        assertTrue(sent);
        uint256 before = address(c).balance;
        c.withdraw(amount);
        // general rule: a partial withdrawal leaves before - amount in the contract
        assertTrue(address(c).balance == before - amount);
    }
}

