pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount) public {
        // Fund the contract with a deterministic, generous balance via its payable fallback.
        vm.deal(address(this), type(uint256).max / 2);
        payable(address(c)).transfer(type(uint256).max / 2);
        uint256 balBefore = address(c).balance;

        // Admissible domain: withdraw a positive amount not exceeding the balance,
        // so the reference's transfer(v) succeeds and moves exactly v wei.
        amount = bound(amount, 1, balBefore);

        // Owner (this contract, the deployer) withdraws `amount`.
        vm.prank(address(this));
        c.withdraw(amount);

        // General rule: balance drops by exactly the withdrawn amount.
        assertTrue(address(c).balance == balBefore - amount);
    }
}

