pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(c));
        amount = bound(amount, 0, 1 ether);
        vm.deal(address(c), 1 ether);
        // adversarial counterparty: callee that re-enters c's fallback (empty calldata)
        ReentrantAcceptor acceptor = new ReentrantAcceptor(c);
        uint256 before = c.depositsCount();
        vm.prank(actor);
        c.sendMoney(address(acceptor), amount);
        assertTrue(c.depositsCount() == before + 1);
    }
}

contract ReentrantAcceptor {
    C immutable c;
    constructor(C _c) { c = _c; }
    fallback() external payable {
        (bool ok, ) = address(c).call{value: 0}("");
        require(ok);
    }
}

